" stroke="#16a34a"/>\n  <text x="555" y="118" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">Birler Bölüğü</text>\n  <text x="555" y="142" text-anchor="middle" font-size="11" fill="#334155">"yedi" (3 hane!)</text>\n  <text x="555" y="162" text-anchor="middle" font-size="16" font-weight="bold" fill="#be123c">007</text>\n\n  <text x="350" y="205" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">Sonuç: 106 045 007 (En sağdaki iki bölük mutlaka 3 basamağa sıfırla tamamlanır!)</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
